function deferPrimitive(value) {
  const valid = value === null || typeof value === 'string' || typeof value === 'boolean' ||
    (typeof value === 'number' && Number.isFinite(value));
  if (!valid) throw new TypeError('Expected a primitive');
  return new Promise((resolve) => queueMicrotask(() => resolve(value)));
}

function scalePhrase(options) {
  if (options === null || typeof options !== 'object' || Array.isArray(options) ||
      Object.keys(options).length !== 2 || typeof options.phrase !== 'string' ||
      typeof options.factor !== 'number' || !Number.isFinite(options.factor)) {
    throw new TypeError('Invalid options');
  }
  return new Promise((resolve) =>
    queueMicrotask(() => resolve(`Scaled ${options.phrase} by ${options.factor}`))
  );
}

async function labelSteps(names) {
  if (!Array.isArray(names) || names.some((name) => typeof name !== 'string')) {
    throw new TypeError('Expected string array');
  }
  const source = names;
  const result = [];
  while (source.length > 0) {
    const name = source.shift();
    await new Promise((resolve) => queueMicrotask(resolve));
    result.push(`Step: ${name}`);
  }
  return result;
}

module.exports = { deferPrimitive, scalePhrase, labelSteps };

