'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['deferPrimitive', 'scalePhrase', 'labelSteps']);
const { deferPrimitive, scalePhrase, labelSteps } = api;

(async () => {
  for (const value of [null, '', 'hello', true, false, 0, -3.5, Number.MAX_VALUE]) {
    const promise = deferPrimitive(value);
    assert.ok(promise instanceof Promise);
    let settled = false;
    promise.then(() => { settled = true; });
    assert.equal(settled, false);
    assert.strictEqual(await promise, value);
  }
  for (const bad of [undefined, NaN, Infinity, -Infinity, {}, [], Symbol('x'), 1n]) {
    assert.throws(() => deferPrimitive(bad), TypeError);
  }

  const options = Object.freeze({ phrase: 'blue moon', factor: -2.5 });
  const scaledPromise = scalePhrase(options);
  assert.ok(scaledPromise instanceof Promise);
  let scaledSettled = false;
  scaledPromise.then(() => { scaledSettled = true; });
  assert.equal(scaledSettled, false);
  assert.equal(await scaledPromise, 'Scaled blue moon by -2.5');
  assert.deepStrictEqual(options, { phrase: 'blue moon', factor: -2.5 });
  assert.equal(await scalePhrase({ phrase: '', factor: 0 }), 'Scaled  by 0');
  for (const bad of [
    null, [], 'x', {},
    { phrase: 'x' },
    { phrase: 'x', factor: 1, extra: true },
    { phrase: 1, factor: 1 },
    { phrase: 'x', factor: '1' },
    { phrase: 'x', factor: NaN },
    { phrase: 'x', factor: Infinity }
  ]) assert.throws(() => scalePhrase(bad), TypeError);

  const names = Object.freeze(['plan', '', 'ship']);
  const labels = await labelSteps(names);
  assert.deepStrictEqual(labels, ['Step: plan', 'Step: ', 'Step: ship']);
  assert.deepStrictEqual(names, ['plan', '', 'ship']);
  assert.deepStrictEqual(await labelSteps([]), []);
  const labelsAgain = await labelSteps(['plan', '', 'ship']);
  assert.notStrictEqual(labelsAgain, labels);
  labels[0] = 'changed';
  assert.deepStrictEqual(labelsAgain, ['Step: plan', 'Step: ', 'Step: ship']);

  for (const bad of [null, {}, 'name', [1], ['ok', false]]) {
    let returned;
    assert.doesNotThrow(() => { returned = labelSteps(bad); });
    assert.ok(returned instanceof Promise);
    await assert.rejects(returned, TypeError);
  }
})().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

